CREATE TABLE "architecture_documents" (
  "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "code" varchar(20) NOT NULL DEFAULT acp_generate_public_code(),
  "project_id" bigint NOT NULL,
  "title" text NOT NULL,
  "summary" text NOT NULL DEFAULT '',
  "content_kind" text NOT NULL,
  "current_revision" integer NOT NULL DEFAULT 1,
  "owner_principal_id" bigint NOT NULL,
  "created_at" text NOT NULL,
  "updated_at" text NOT NULL,
  CONSTRAINT "ck_architecture_documents_code" CHECK ("code" ~ '^[0-9A-HJKMNP-TV-Z]{20}$'),
  CONSTRAINT "ck_architecture_documents_kind" CHECK ("content_kind" IN ('mermaid', 'drawio', 'image')),
  CONSTRAINT "ck_architecture_documents_revision" CHECK ("current_revision" > 0)
);
