CREATE TABLE "architecture_document_revisions" (
  "id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "code" varchar(20) NOT NULL DEFAULT acp_generate_public_code(),
  "document_id" bigint NOT NULL,
  "revision" integer NOT NULL,
  "title" text NOT NULL,
  "summary" text NOT NULL DEFAULT '',
  "content_kind" text NOT NULL,
  "source_content" text NOT NULL,
  "notes_markdown" text NOT NULL DEFAULT '',
  "preview_svg" text,
  "change_summary" text NOT NULL,
  "created_by" bigint NOT NULL,
  "created_at" text NOT NULL,
  CONSTRAINT "ck_architecture_document_revisions_code" CHECK ("code" ~ '^[0-9A-HJKMNP-TV-Z]{20}$'),
  CONSTRAINT "ck_architecture_document_revisions_revision" CHECK ("revision" > 0),
  CONSTRAINT "ck_architecture_document_revisions_kind" CHECK ("content_kind" IN ('mermaid', 'drawio', 'image')),
  CONSTRAINT "ck_architecture_document_revisions_source_size" CHECK (octet_length("source_content") BETWEEN 1 AND 6291456),
  CONSTRAINT "ck_architecture_document_revisions_preview_size" CHECK ("preview_svg" IS NULL OR octet_length("preview_svg") <= 2097152)
);
